<?php declare(strict_types=1); require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session]=$context=admin_empresa_context(); try{$app->companyAdmin()->link((int)($_POST['empresa_id']??0),(int)($_POST['fornecedor_so_id']??0),$app->soSupplierService());$session->flash('success','Fornecedor vinculado à empresa.');}catch(InvalidArgumentException $e){$session->flash('danger',$e->getMessage());}catch(Throwable $e){error_log('Company SO link failed: '.get_class($e));$session->flash('danger','Não foi possível vincular o fornecedor.');}admin_empresa_redirect($app);
